package com.smartproperty.platform.residentportal.controller;
import com.smartproperty.platform.residentportal.dto.*;import com.smartproperty.platform.residentportal.service.ResidentPortalService;import com.smartproperty.platform.residentportal.vo.ResidentPortalVO.*;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/resident/me") public class ResidentPortalController {private final ResidentPortalService s;public ResidentPortalController(ResidentPortalService x){s=x;}@GetMapping("/summary")public SummaryVO summary(){return s.summary();}@GetMapping("/residences")public List<ResidenceVO> residences(){return s.residences();}@GetMapping("/properties")public List<PropertyVO> properties(){return s.properties();}@GetMapping("/bills")public List<BillVO>bills(){return s.bills();}@GetMapping("/notifications")public List<NotificationVO>notifications(){return s.notifications();}@GetMapping("/incidents")public List<IncidentVO>incidents(){return s.myIncidents();}@PostMapping("/incidents")public IncidentVO submit(@Valid @RequestBody ResidentIncidentCreateRequest r){return s.submitIncident(r);}}
